decl_692.source:
def assignSlot (m : ℕ) (v : V) : Option ℕ :=
  let A := (range (Q.duration m)).filter (fun k => v ∈ Q.action m k)
  if h : A.Nonempty then some (A.min' h) else none

decl_726.statement:
∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S) (b : Fin batches),
  B.eligible b ≤ R.boundary (R.admission b)

decl_725.statement:
∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S O : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S),
  0 < m → 0 < L → I.Valid m O → I.FlowBound O L → ∀ (b : Fin batches), R.boundary (R.admission b) ≤ B.eligible b + 4 * L

decl_732.statement:
∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S O : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S),
  0 < m → 0 < L → I.Valid m O → I.FlowBound O L → I.FlowBound S (44 * L ^ 2)

decl_735.statement:
∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S O : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S),
  0 < m → 0 < L → I.Valid m O → I.FlowBound O L → I.maxFlow S ≤ 44 * L ^ 2

decl_892.source:
def sffStep (m : ℕ) (_t : ℕ) (observation : PublicSnapshot) (state : SFFMemory) :
    Finset ℕ × SFFMemory :=
  let plan := state.getD (observation, 0)
  (plan.1.action m plan.2,
    if plan.2 + 1 < plan.1.duration m then some (plan.1, plan.2 + 1) else none)

decl_729.statement:
∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S) (k : ℕ),
  m * (R.boundary (k + 1) - R.boundary k) ≤ (R.smallFront k).card + m

decl_744.statement:
∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S) (a k : ℕ),
  (R.smallFront k).card ≤ (R.oldService a k).card + (R.youngFront a k).card

decl_737.statement:
∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S) {A K : ℕ},
  A ≤ K → ∑ k ∈ Finset.Ico A K, (R.oldService (R.boundary A) k).card ≤ (B.admittedRemaining S (R.boundary A)).card

decl_734.statement:
∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S) {A K : ℕ},
  A ≤ K → ∑ k ∈ Finset.Ico A K, (R.boundary (k + 1) - R.boundary k) = R.boundary K - R.boundary A

decl_426.source:
def readyObservation (S : Assignment (vertices := vertices)) (t : ℕ) : FIFOObservation :=
  (univ.filter (fun v => I.release (I.owner v) ≤ t ∧ t ≤ S v ∧
    ∀ u, I.edge u v → S u < t)).image I.fifoPriority

decl_748.statement:
∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S) {k : ℕ} {b : Fin batches},
  b ∈ R.switches k → ∃ v, B.vertexBatch v = b ∧ R.boundary k ≤ S v ∧ S v < R.boundary (k + 1)

decl_741.statement:
∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S),
  0 < m → ∀ (k : ℕ), R.boundary (k + 1) - R.boundary k ≤ max 1 (B.small m S (R.boundary k)).card

decl_728.statement:
∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S) {K a D : ℕ},
  a ≤ K → (∀ k < K, R.boundary (k + 1) - R.boundary k ≤ D) → R.boundary K ≤ R.boundary a + (K - a) * D

decl_730.statement:
∀ {jobs vertices batches m L : ℕ} {I : Scheduling.Instance jobs vertices} {B : Scheduling.Batching I L batches}
  {S : Scheduling.Assignment} (R : Scheduling.SFFRounds B m S) {u K t : ℕ},
  u ≤ K → R.boundary u ≤ t → t < R.boundary K → ∃ r, u ≤ r ∧ r < K ∧ R.boundary r ≤ t ∧ t < R.boundary (r + 1)

decl_756.source:
def MiddleAt (long : Fin jobs → Bool) (hm : 0 < m)
    (S : Assignment (vertices := jobs * (3 * m))) (t : ℕ) : Prop :=
  ∃ j, long j = true ∧ S (middle hm j) = t

decl_763.statement:
∀ {jobs m : ℕ} (A : Scheduling.DeterministicScheduler m) (hm : 0 < m) (long : Fin jobs → Bool) (j : Fin jobs)
  (b : Bool),
  have I := Scheduling.StarChain.toInstance long hm;
  have J := Scheduling.StarChain.toInstance (Function.update long j b) hm;
  ∀ t ≤ A.schedule I (Scheduling.StarChain.root hm j),
    ∀ (v : Fin (jobs * (3 * m))), A.schedule I v = t ↔ A.schedule J v = t

decl_774.source:
def leafParent (long : Fin jobs → Bool) (hm : 0 < m)
    (v : Fin (jobs * (3 * m))) : Fin (jobs * (3 * m)) :=
  if long (job v) then middle hm (job v) else root hm (job v)
